INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28a-2016-q41','exam-sg','システム移行テスト','standard','single_choice','【2016年度 平成28年秋期 午前 問41】システムの移行テストを実施する主要な目的はどれか。','[{"id":"a","text":"確実性や効率性の観点で，既存システムから新システムへの切替え手順や切替えに伴う問題点を確認する。"},{"id":"b","text":"既存システムの実データのコピーを利用して，新システムでも十分な性能が得られることを確認する。"},{"id":"c","text":"既存の他システムと新規開発プログラムとのインタフェースの整合性を確認する。"},{"id":"d","text":"新システムが要求された全ての機能を満たしていることを確認する。"}]','"a"','正解はア。移行テストでは，旧システムから新システムへの切替え手順や移行時の問題を検証する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q42','exam-sg','ITサービスマネジメント・インシデント','standard','single_choice','【2016年度 平成28年秋期 午前 問42】受発注管理システムの運用中に起きた事象のうち，インシデントに該当するものはどれか。夜間バッチ処理で注文書出力プログラムが異常終了し，運用担当者から連絡を受けた保守担当者が緊急出社してサービスを回復し，後日プログラムの誤りを修正した。','[{"id":"a","text":"異常終了の検知"},{"id":"b","text":"プログラムの誤り"},{"id":"c","text":"プログラムの異常終了"},{"id":"d","text":"保守担当者の緊急出社"}]','"c"','正解はウ。インシデントはサービスの中断や品質低下など，利用者に影響する事象であり，この場合はプログラムの異常終了が該当する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q43','exam-sg','バックアップ・復旧目標','standard','single_choice','【2016年度 平成28年秋期 午前 問43】メールサーバの障害で多数のメールが消失した。2週間ごとのフルバックアップしかなく，最後のバックアップ以降1週間分を復旧できなかった。前日の状態まで復旧できるようにする対策として適切なものはどれか。','[{"id":"a","text":"2週間ごとのフルバックアップに加え，毎日，磁気テープへの差分バックアップを行う。"},{"id":"b","text":"電子メールを複数のディスクに分散して蓄積する。"},{"id":"c","text":"バックアップは現状のままにし，メールサーバのディスクをミラーリングする。"},{"id":"d","text":"毎日フルバックアップを行い，2週間ごとにバックアップデータを磁気テープにコピーする。"}]','"a"','正解はア。日次の差分バックアップを追加すると，フルバックアップ後の変更を日ごとに保存でき，復旧時点を前日に近づけられる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q44','exam-sg','プロジェクト管理・ステークホルダ','standard','single_choice','【2016年度 平成28年秋期 午前 問44】プロジェクトに関わるステークホルダの説明のうち，適切なものはどれか。','[{"id":"a","text":"ステークホルダは組織外部には存在せず，組織内部に属している。"},{"id":"b","text":"プロジェクトの成果が，自らの利益になる者と不利益になる者がいる。"},{"id":"c","text":"ステークホルダの関与は間接的なものにとどまらず，必ず直接参加する。"},{"id":"d","text":"プロジェクトマネージャのように，個人として特定できることが必要である。"}]','"b"','正解はイ。ステークホルダには成果から利益を得る者だけでなく，不利益や影響を受ける者も含まれる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q45','exam-sg','システム構成・Webクライアント','standard','single_choice','【2016年度 平成28年秋期 午前 問45】クライアントサーバシステムを構築する際，専用アプリケーションの代わりにWebブラウザでクライアント処理を行うと，最も軽減される作業はどれか。','[{"id":"a","text":"クライアント環境の保守"},{"id":"b","text":"データベースの構築"},{"id":"c","text":"サーバが故障したときの復旧"},{"id":"d","text":"ログインアカウントの作成と削除"}]','"a"','正解はア。ブラウザ方式では専用クライアントアプリの配布・更新が不要になり，クライアント環境の保守負担を減らせる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q46','exam-sg','データベース設計・E-R図','standard','single_choice','【2016年度 平成28年秋期 午前 問46】E-R図に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"関係データベースの表として実装することを前提に表現する。"},{"id":"b","text":"管理対象をエンティティ及びエンティティ間のリレーションシップとして表現する。"},{"id":"c","text":"データの生成から消滅までのデータ操作を表現する。"},{"id":"d","text":"リレーションシップは業務上の手順を表現する。"}]','"b"','正解はイ。E-R図はデータの対象（エンティティ）と対象間の関係（リレーションシップ）を表現する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q47','exam-sg','ネットワーク・DHCP','standard','single_choice','【2016年度 平成28年秋期 午前 問47】DHCPサーバが設置されたLAN環境の説明のうち，適切なものはどれか。','[{"id":"a","text":"DHCPを使うPCではIPアドレスだけが自動設定され，サブネットマスクやデフォルトゲートウェイは自動設定できない。"},{"id":"b","text":"DHCPを使うPCと，IPアドレスが固定のPCを混在させることはできない。"},{"id":"c","text":"DHCPを使うPCに，DHCPサーバのアドレスをあらかじめ設定しておく必要はない。"},{"id":"d","text":"一度IPアドレスを割り当てられたPCは，電源を切っても必ず同じIPアドレスが割り当てられる。"}]','"c"','正解はウ。DHCPクライアントはブロードキャスト等で設定情報を取得するため，通常DHCPサーバのアドレスを事前設定する必要はない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q48','exam-sg','業務プロセス・BPO','standard','single_choice','【2016年度 平成28年秋期 午前 問48】BPOの説明はどれか。','[{"id":"a","text":"災害や事故が起きても重要事業を中断させない，又は中断期間を短くする仕組みを構築すること"},{"id":"b","text":"コアビジネスではない社内業務の一部又は全部を，外部の専門企業に委託すること"},{"id":"c","text":"生産に必要な部品数量や資材所要量・時期を計算する生産管理手法"},{"id":"d","text":"情報化投資を戦略適合性，費用対効果，リスクなどから評価し最適化すること"}]','"b"','正解はイ。BPO（Business Process Outsourcing）は，業務プロセスの一部または全部を外部の専門事業者へ委託することを指す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q49','exam-sg','システム企画・共通フレーム','standard','single_choice','【2016年度 平成28年秋期 午前 問49】共通フレームによれば，企画プロセスにおいて明確にするものはどれか。','[{"id":"a","text":"新しい業務の在り方や手順，入出力情報，業務上の責任と権限，業務ルールや制約"},{"id":"b","text":"業務要件を実現するシステム機能，開発方式，運用手順，障害復旧時間"},{"id":"c","text":"経営・事業の目的と目標を達成するために必要なシステムに関する経営上のニーズや業務上の課題"},{"id":"d","text":"ソフトウェアの機能・能力，動作環境，外部インタフェース，運用・保守方法"}]','"c"','正解はウ。企画プロセスでは，経営・事業目標と関連付けてシステム化の必要性や業務課題を明確にする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja'),
('sg-official-h28a-2016-q50','exam-sg','組織論・マトリックス組織','standard','single_choice','【2016年度 平成28年秋期 午前 問50】マトリックス組織を説明したものはどれか。','[{"id":"a","text":"機能と利益責任を製品別・顧客別・地域別にもつことで，自己完結的な経営活動を展開できる組織"},{"id":"b","text":"構成員が，専門とする職能部門と特定の事業を遂行する部門の両方に所属する組織"},{"id":"c","text":"購買・生産・販売・財務など，専門性によって機能分化された部門をもつ組織"},{"id":"d","text":"特定の課題の下に各部門から専門家を集め，期間と目標を定めて活動する一時的で柔軟な組織"}]','"b"','正解はイ。マトリックス組織では，構成員が職能部門とプロジェクト・事業部門の双方に所属する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000g6fw-att/2016h28a_sg_am_qs.pdf','ja');
